import{z as n,x as o,o as A,c as d,q as t,j as i,D as B,d as e,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"逐层与逐头的敏感度","description":"","frontmatter":{"title":"逐层与逐头的敏感度","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-layerwise-sensitivity.md","filePath":"llm/kv-layerwise-sensitivity.md","lastUpdated":1791063341000}'),D={name:"llm/kv-layerwise-sensitivity.md"};function p(m,E,C,h,f,u){const l=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="逐层与逐头的敏感度" tabindex="-1">逐层与逐头的敏感度 <a class="header-anchor" href="#逐层与逐头的敏感度" aria-label="Permalink to &quot;逐层与逐头的敏感度&quot;">​</a></h1><div class="epigraph"><p>误差预算在网络深度上不是均匀货币：同样一比特花在第一层和第三十层，买到的质量不一样。</p><footer>—— 据 Liu et al., KIVI, ICML 2024 的逐层量化敏感性观察；配额视角见 Cai et al., PyramidKV, 2024</footer></div><p><a href="/llm/kv-quant-int8-int4">上一课</a>把所有层、所有头一视同仁地压到同一档。缺口是：误差预算在深度与头之间的分布不均匀——同样的 4-bit，有的层几乎无感，有的层掉点；同样的驱逐配额，有的头是检索主干，有的头全程陪跑。统一策略把预算花在无感处，把刀落在要害处。本课写敏感度怎么量出来、预算怎么按层按头重排。量化轴与头数的结构权衡各有先课，不重写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>统一策略隐含「各层各头同质」。两条证据反对它。量化侧：KIVI 在流行模型上观察到第一层对低比特最敏感，同样操作在中间层几乎免费。驱逐侧：注意力角色沿深度分化——浅层的注意力弥散在整个上下文上，深层则集中到少数锚点，信息像通过漏斗收窄；<a href="/llm/attention-head-roles">头角色</a>也早已分化，归纳头与检索头承载长程复制，负头的分布近乎均匀。对浅层驱逐、对检索头量化，都是在最不耐受的位置下刀。</p><p>敏感度还随负载变：检索型任务把要害押在少数长程头上，闲聊负载几乎测不出差别。所以敏感度不是模型的一个常数，而是「模型 × 任务」的性质，测量必须带着目标负载做。</p><p><span class="marginnote">直觉类比：把误差预算想成装修预算——统一策略像每个房间花一样的钱，结果在储藏间铺了大理石，却给承重墙用了劣质水泥。按敏感度重排预算，就是把材料挪到承重的地方，总花费不变、房子更稳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>量出来</strong>。对每层每头做受控消融：单独把该层量化到目标比特、或单独纳入驱逐集，在针检索与长文档任务上量 delta，困惑度只做粗筛。廉价的代理是注意力的集中度（分数熵）：弥散的层/头对扰动耐受，尖峰的对扰动敏感，可先按熵排序再做精确消融。扫描离线做一次，部署时查表。</p><p><span class="marginnote">术语翻译：受控消融就是一次只动一个开关——单独把某一层的缓存压到 4-bit，或单独把它划进驱逐集，其余一切不变，再量任务分数掉了多少。掉得多，说明这一处敏感；一次动多个开关，就说不清掉点是谁的锅。</span></p><p><strong>用出来</strong>。两条再分配的轴。精度轴：敏感层保 FP8/FP16，其余打 INT4，平均比特不变、掉点显著收窄。配额轴：驱逐预算按层重排——浅层多留、深层少留，与漏斗形状一致；同一层内，检索头与汇点位置禁逐，负头先逐。<a href="/llm/h2o-kv">H2O</a> 的累积分数可以当逐头的驱逐判据，但它不分层；把分数与层位联用，才接近「预算花在刀刃上」。</p>',11)),(A(),i(s,null,{default:B(()=>[r(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCAN%5B%22%E7%A6%BB%E7%BA%BF%E6%89%AB%E6%8F%8F%EF%BC%9A%E9%80%90%E5%B1%82%E9%80%90%E5%A4%B4%E6%B6%88%E8%9E%8D%22%5D%20--%3E%20TAB%5B%22%E6%95%8F%E6%84%9F%E5%BA%A6%E8%A1%A8%EF%BC%9A%E5%B1%82%20%C3%97%20%E5%A4%B4%22%5D%0A%20%20TAB%20--%3E%20PREC%7B%22%E7%B2%BE%E5%BA%A6%E8%BD%B4%E5%88%86%E9%85%8D%22%7D%0A%20%20TAB%20--%3E%20QUOTA%7B%22%E9%85%8D%E9%A2%9D%E8%BD%B4%E5%88%86%E9%85%8D%22%7D%0A%20%20PREC%20--%3E%7C%22%E6%95%8F%E6%84%9F%E5%B1%82%22%7C%20HI%5B%22FP8%20%2F%20FP16%22%5D%0A%20%20PREC%20--%3E%7C%22%E8%80%90%E5%8F%97%E5%B1%82%22%7C%20LO%5B%22INT4%22%5D%0A%20%20QUOTA%20--%3E%7C%22%E6%B5%85%E5%B1%82%20%2F%20%E6%A3%80%E7%B4%A2%E5%A4%B4%22%7C%20KEEP%5B%22%E5%A4%9A%E9%85%8D%E9%A2%9D%E6%88%96%E7%A6%81%E9%80%90%22%5D%0A%20%20QUOTA%20--%3E%7C%22%E6%B7%B1%E5%B1%82%20%2F%20%E8%B4%9F%E5%A4%B4%22%7C%20CUT%5B%22%E5%85%88%E5%8E%8B%E5%85%88%E9%80%90%22%5D%0A%20%20HI%20--%3E%20MIX%5B%22%E6%B7%B7%E7%B2%BE%E5%BA%A6%E7%BC%93%E5%AD%98%22%5D%0A%20%20KEEP%20--%3E%20MIX%0A%20%20CUT%20--%3E%20MIX%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"层间不均的机制在信息流：早期层处理局部的词序与句法，需要「看得宽」，注意力熵高、可删的少；深层做语义聚合，只对少量锚点打分，砍掉无人看的位置损失很小。金字塔式的配额（浅层厚、深层薄）就是这个形状的直接翻译。量化敏感度同构：第一层的键承担了「定位自己在哪」的基础功能，通道异常最深，压它等于动摇配分函数。",-1)),E[5]||(E[5]=a("p",null,[e("头维的机制在角色分工：归纳头负责把当前 token 链接到早前出现的位置，是上下文学习载体的那批头，丢了它们的键，少样本能力先崩；负头只做均匀背景，是天然的压缩对象。GQA 之后头维只剩 \\(h_{kv}\\) 个独立键值组，一切按头策略必须以 KV 头为单位执行，粒度先被结构钉死——这是 "),a("a",{href:"/llm/kv-head-tradeoff"},"KV 头数权衡"),e(" 给出的约束，不是实现选择。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：GQA 把 32 个查询头共享到 \\(h_{kv}=8\\) 个 KV 组后，「按头定精度」的可操作对象就从 32 掉到 8——想给某个查询头单独保 FP16，也只能连同共享这一组键值的兄弟头一起保。说「策略粒度被结构钉死」，指的就是这种想动一处、必动一组的情况。")],-1)),(A(),i(s,null,{default:B(()=>[r(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%85%A8%E9%83%A8%20n%20%E4%B8%AA%E4%BD%8D%E7%BD%AE%E9%83%BD%E5%9C%A8%E7%BC%93%E5%AD%98%E9%87%8C%22%5D%20--%3E%20SH%5B%22%E6%B5%85%E5%B1%82%3A%20%E7%86%B5%E9%AB%98%2C%20%E6%B3%A8%E6%84%8F%E5%8A%9B%E9%93%BA%E6%BB%A1%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20SH%20--%3E%20X1%5B%22%E6%AF%8F%E4%B8%AA%E4%BD%8D%E7%BD%AE%E9%83%BD%E6%9C%89%E4%BA%BA%E7%9C%8B%3A%20%E5%88%A0%E8%B0%81%E5%8E%8B%E8%B0%81%E9%83%BD%E7%97%9B%22%5D%0A%20%20T%20--%3E%20MD%5B%22%E4%B8%AD%E5%B1%82%3A%20%E5%85%B3%E6%B3%A8%E9%9D%A2%E9%80%90%E6%AD%A5%E6%94%B6%E7%AA%84%22%5D%0A%20%20MD%20--%3E%20DP%5B%22%E6%B7%B1%E5%B1%82%3A%20%E7%86%B5%E4%BD%8E%2C%20%E5%8F%AA%E7%9B%AF%E5%B0%91%E6%95%B0%E9%94%9A%E7%82%B9%22%5D%0A%20%20DP%20--%3E%20X2%5B%22%E6%97%A0%E4%BA%BA%E7%9C%8B%E7%9A%84%E4%BD%8D%E7%BD%AE%E5%8F%AF%E5%85%88%E5%88%A0%E5%85%88%E5%8E%8B%3A%20%E8%80%90%E5%8F%97%22%5D%0A%20%20X1%20--%3E%20PY%5B%22%E9%87%91%E5%AD%97%E5%A1%94%E9%85%8D%E9%A2%9D%3A%20%E6%B5%85%E5%B1%82%E7%95%99%E5%8E%9A%2C%20%E6%B7%B1%E5%B1%82%E5%8E%8B%E8%96%84%22%5D%0A%20%20X2%20--%3E%20PY%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">敏感度表要在「模型 × 负载」两维上建档：同一次扫描给出的排序，搬到检索型负载上可能整体重排。换了主力任务不改表，等于拿着旧地图开车。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>混精度把缓存切成多种粒度，核必须支持逐块不同比特，前缀缓存的<a href="/llm/kv-prefix-cache">指纹</a>要把「哪层哪头什么精度」一并编进键，否则跨请求共享会命中到不一致的页。逐层驱逐与滑窗、sink 配方叠加时，禁逐区要取并集，别让两条策略互相拆台。离线扫描有分布漂移：模型升级、提示模板大改之后敏感度排序会变，表要随版本重扫。最后，别把「深层不敏感」推到极端——最深几层直接接输出分布，残差里的值误差会放大，压缩方案通常给首末层单独留档。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>敏感度是「模型 × 任务」性质：用受控消融加注意力熵代理量出来，离线扫描、部署查表。</li><li>精度轴与配额轴都可以按层按头重排；金字塔分配与信息漏斗形状一致。</li><li>浅层最怕量化与驱逐；检索头、归纳头与汇点位置禁逐，负头先压。</li><li>GQA 把头策略的粒度钉在 KV 头上；混精度进缓存指纹。</li><li>首末层单独留档；表随模型与负载版本重扫。</li><li>出处：Liu et al., KIVI, ICML 2024（逐层敏感性）；Cai et al., PyramidKV, 2024（按层配额）；头角色口径据本仓库既有课程。</li></ul>',5))])}const F=n(D,[["render",p]]);export{T as __pageData,F as default};
